{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Morphine, the closest retrieved analogue, showed an absolute oral bioavailability of 48.2% in a patient, directly supporting F≥20% for this morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Codeine, a close 3-methoxy morphinan, has an estimated oral bioavailability of 84±5%, showing that related morphinans can achieve high oral systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Nalmefene, a structurally related morphinan opioid, has an absolute oral bioavailability of about 53% with food, supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Naltrexone, a related 6-keto morphinan, showed only about 5% oral bioavailability in healthy volunteers, representing a low-F outlier due to extensive first-pass metabolism.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is hydromorphone, a morphinan opioid. Close analogues such as morphine, codeine, and nalmefene have oral bioavailability values predominantly above 20%, and the structural features of hydromorphone are consistent with moderate oral bioavailability. Rifampin co-treatment may reduce exposure through enzyme/P-gp induction, but the weight of evidence supports F≥20%.",
  "evidence_gaps": [
    "No direct hydromorphone oral bioavailability measurement under rifampin co-treatment is present.",
    "No rifampin interaction data for close analogues are available; the magnitude of first-pass induction is inferred."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

